<script setup lang="ts">import{ref}from'vue';import{onLoad,onPullDownRefresh}from'@dcloudio/uni-app';import WareState from '@/shared/components/WareState.vue';import{cartonInventoryApi,type MaterialApply}from'../../api/carton-inventory.api';const tabs=[['全部',0],['待审核',10],['已同意',20],['已拒绝',30],['已撤销',40]] as const;const status=ref(0),list=ref<MaterialApply[]>([]),loading=ref(true),error=ref(''),active=ref<MaterialApply|null>(null),saving=ref(false);const statusName=(s:number)=>({10:'待审核',20:'已同意',30:'已拒绝',40:'已撤销'}[s]||'未知');async function load(){loading.value=true;try{list.value=await cartonInventoryApi.applications(status.value);error.value=''}catch(e){error.value=e instanceof Error?e.message:'申领记录加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}async function audit(ok:boolean){if(!active.value||saving.value)return;saving.value=true;try{await cartonInventoryApi.audit(active.value.id,{approved:ok,quantity:active.value.apply_quantity,reason:ok?'':'审核拒绝'});active.value=null;uni.showToast({title:'审核完成',icon:'success'});load()}finally{saving.value=false}}onLoad(load);onPullDownRefresh(load);</script>
<template><view class="page"><view class="intro"><b>申领审核</b><text>查看并处理各分区纸箱申领</text></view><view class="tabs"><text v-for="t in tabs" :key="t[1]" :class="{active:status===t[1]}" @click="status=t[1];load()">{{t[0]}}</text></view><WareState v-if="loading||error||!list.length" :type="loading ? 'loading' : error ? 'error' : 'empty'" :title="loading ? '正在加载' : error ? '加载失败' : '暂无申领记录'" :description="error" :action-label="error ? '重新加载' : undefined" @action="load"/><view v-for="x in list" :key="x.id" class="card"><view class="card-top"><b :class="`s${x.status}`">● {{statusName(x.status)}}</b><small>{{x.apply_no}}</small></view><view class="details"><text>申领大区</text><b>{{x.team_name}}</b><text>申领负责人</text><b>{{x.applicant_name}}</b><text>物资规格</text><b>{{x.specification}}</b><text>申领数量</text><b>{{x.apply_quantity}}{{x.unit_name}}</b><text>实际发放</text><b>{{x.issued_quantity||0}}{{x.unit_name}}</b><text>申请时间</text><b>{{x.create_time}}</b></view><button @click="active=x">查看详情</button></view><view v-if="active" class="mask" @click="active=null"><view class="drawer" @click.stop><view class="drawer-head"><b>{{statusName(active.status)}}</b><text>{{active.apply_no}}</text></view><view class="details"><text>申领团队</text><b>{{active.team_name}}</b><text>申领负责人</text><b>{{active.applicant_name}}</b><text>纸箱规格</text><b>{{active.specification}}</b><text>申领/发放数量</text><b>{{active.apply_quantity}} / {{active.issued_quantity||0}}{{active.unit_name}}</b><text>申请时间</text><b>{{active.create_time}}</b><text>审核人</text><b>{{active.auditor_name||'待审核'}}</b><text>备注</text><b>{{active.remark||'无'}}</b></view><view v-if="active.status===10" class="audit"><button @click="audit(false)">拒绝</button><button @click="audit(true)">同意并出库</button></view><button v-else class="close" @click="active=null">关闭</button></view></view></view></template>
<style scoped>.page{min-height:100vh;padding:20rpx;background:var(--wms-background)}.intro b,.intro text{display:block}.intro b{font-size:29rpx}.intro text{margin-top:4rpx;color:var(--wms-text-secondary);font-size:19rpx}.tabs{display:flex;justify-content:space-around;margin:18rpx -20rpx 16rpx;border-bottom:1rpx solid var(--wms-border);background:#fff}.tabs text{padding:16rpx 4rpx;font-size:20rpx}.tabs .active{border-bottom:4rpx solid var(--wms-primary-700);color:var(--wms-primary-700);font-weight:600}.card{margin-bottom:14rpx;padding:20rpx;border:1rpx solid var(--wms-border);border-radius:14rpx;background:#fff}.card-top{display:flex;justify-content:space-between}.card-top b{color:var(--wms-success)}.card-top .s10{color:var(--wms-warning)}.card-top .s30,.card-top .s40{color:var(--wms-danger)}.card-top small{color:var(--wms-text-secondary)}.details{display:grid;grid-template-columns:145rpx 1fr;gap:12rpx;margin-top:18rpx;font-size:20rpx}.details text{color:var(--wms-text-secondary)}.details b{text-align:right}.card button{display:block;width:auto;margin:18rpx 0 0 auto;padding:0 22rpx;border:1rpx solid var(--wms-primary-700);border-radius:24rpx;background:#fff;color:var(--wms-primary-700);font-size:19rpx;line-height:52rpx}.mask{position:fixed;z-index:80;inset:0;display:flex;align-items:flex-end;background:#0007}.drawer{box-sizing:border-box;min-height:58vh;width:100%;padding:26rpx 24rpx calc(24rpx + env(safe-area-inset-bottom));border-radius:24rpx 24rpx 0 0;background:#fff}.drawer-head{display:flex;justify-content:space-between}.drawer-head text{color:var(--wms-text-secondary);font-size:19rpx}.audit{display:grid;grid-template-columns:1fr 1fr;gap:12rpx;margin-top:30rpx}.audit button,.close{margin:0;border-radius:8rpx;font-size:21rpx}.audit button:last-child,.close{background:var(--wms-primary-700);color:#fff}.close{position:absolute;right:24rpx;bottom:24rpx;left:24rpx;width:calc(100% - 48rpx)}</style>
